#include <iostream>
#include <string>
using namespace std;

string findSaras(int n) {
    string messages[] = {
        "You found Saras in the kitchen and haunted school",
        "You saw Saras from a far, in the backyard and well",
        "Saras poke on your shoulder in the music room",
        "You sage the old house and the bathroom",
        "You almost ran out of sage after you went in the basement and attic",
        "You threw away the map that smells like sage in the garage"
    };

    if (n >= 1 && n <= 2)
        return messages[0];
    else if (n >= 3 && n <= 4)
        return messages[1];
    else if (n == 5)
        return messages[2];
    else if (n >= 6 && n <= 7)
        return messages[3];
    else if (n >= 8 && n <= 9)
        return messages[4];
    else if (n == 10)
        return messages[5];

    return "";
}

int main() {
    int n;
    cin >> n;

    cout << findSaras(n) << endl;

    return 0;
}

